<script setup lang="ts">
import { reactive,ref,onMounted } from 'vue'; import { api,errorMessage } from '../api'; import PageHeader from '../components/PageHeader.vue'; import Modal from '../components/Modal.vue'; import DataTable from '../components/DataTable.vue'; import StatusBadge from '../components/StatusBadge.vue'; import { Plus } from 'lucide-vue-next'
const rows=ref<any[]>([]),open=ref(false),error=ref('');const form=reactive({name:'',slug:'',type:'customer',owner_name:'',owner_email:'',owner_password:''});const cols=[{key:'name',label:'Cliente'},{key:'slug',label:'Identificador'},{key:'type',label:'Tipo'},{key:'status',label:'Situação'},{key:'created_at',label:'Criado em'}]
async function load(){rows.value=(await api.get('/tenants',{headers:{'X-Tenant-ID':''}})).data} async function save(){try{await api.post('/tenants',form,{headers:{'X-Tenant-ID':''}});open.value=false;await load()}catch(e){error.value=errorMessage(e)}} onMounted(load)
</script>
<template><PageHeader title="Clientes e parceiros" subtitle="Administre tenants isolados, parceiros, contabilidades e clientes diretos"><button class="btn primary" @click="open=true"><Plus :size="16"/>Novo cliente</button></PageHeader><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-status="{value}"><StatusBadge :status="value"/></template><template #cell-created_at="{value}">{{ new Date(value).toLocaleDateString('pt-BR') }}</template></DataTable></section><Modal :open="open" title="Cadastrar cliente" @close="open=false"><form class="form-grid" @submit.prevent="save"><label>Nome<input v-model="form.name" required/></label><label>Slug<input v-model="form.slug" required/></label><label>Tipo<select v-model="form.type"><option value="customer">Cliente</option><option value="partner">Parceiro</option></select></label><div class="form-separator">Administrador do cliente</div><label>Nome<input v-model="form.owner_name"/></label><label>E-mail<input v-model="form.owner_email" type="email"/></label><label class="span-2">Senha inicial<input v-model="form.owner_password" type="password" minlength="10"/></label><div v-if="error" class="alert danger span-2">{{error}}</div><div class="form-actions span-2"><button type="button" class="btn" @click="open=false">Cancelar</button><button class="btn primary">Salvar</button></div></form></Modal></template>
